import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ApiService } from '../../services/api.service';
import { AuthService } from '../../services/auth.service';

interface DashboardStats {
  totalStudents: number;
  activeCourses: number;
  totalRevenue: number;
  placedStudents: number;
  placementPercentage: number;
  recentEnrollments: RecentEnrollment[];
  upcomingEvents: UpcomingEvent[];
}

interface RecentEnrollment { studentName: string; courseName: string; date: string; status: string; }
interface UpcomingEvent { eventName: string; eventType: string; date: string; }

interface SaasLine { id: number; name: string; usageCount: number; }
interface RecentOrg { id: number; name: string; slug: string; isActive: boolean; orgSubscriptionName: string | null; createdAt: string; }

interface SaasStats {
  totalOrganizations: number;
  activeOrganizations: number;
  totalOrgAdmins: number;
  totalTeachers: number;
  totalStudents: number;
  totalUsers: number;
  totalSubscriptions: number;
  mrr: number;
  orgsBySubscription: SaasLine[];
  recentOrganizations: RecentOrg[];
}

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule],
  template: `
    @if (auth.isSuperAdmin) {
      <h1 style="font-size:24px;font-weight:700;margin-bottom:24px;">SaaS Platform Dashboard</h1>
      <div class="grid-4">
        <div class="card stat-card"><div class="icon" style="background:#DBEAFE;color:#2563EB;">🏢</div><div><div style="font-size:28px;font-weight:700;">{{ saas.totalOrganizations || 0 }}</div><div style="color:#64748B;font-size:14px;">Total Organizations</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#DCFCE7;color:#22C55E;">✅</div><div><div style="font-size:28px;font-weight:700;">{{ saas.activeOrganizations || 0 }}</div><div style="color:#64748B;font-size:14px;">Active Tenants</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#FEF3C7;color:#EAB308;">💰</div><div><div style="font-size:28px;font-weight:700;">₹{{ saas.mrr | number:'1.0-0' }}</div><div style="color:#64748B;font-size:14px;">Monthly Recurring Revenue</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#F3E8FF;color:#9333EA;">⭐</div><div><div style="font-size:28px;font-weight:700;">{{ saas.totalSubscriptions || 0 }}</div><div style="color:#64748B;font-size:14px;">Subscription Plans</div></div></div>
      </div>
      <div class="grid-4" style="margin-top:16px;">
        <div class="card stat-card"><div class="icon" style="background:#FEE2E2;color:#DC2626;">👤</div><div><div style="font-size:28px;font-weight:700;">{{ saas.totalUsers || 0 }}</div><div style="color:#64748B;font-size:14px;">All Users</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#DBEAFE;color:#2563EB;">👨‍💼</div><div><div style="font-size:28px;font-weight:700;">{{ saas.totalOrgAdmins || 0 }}</div><div style="color:#64748B;font-size:14px;">Org Admins</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#DCFCE7;color:#22C55E;">👨‍🏫</div><div><div style="font-size:28px;font-weight:700;">{{ saas.totalTeachers || 0 }}</div><div style="color:#64748B;font-size:14px;">Teachers</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#FEF3C7;color:#EAB308;">🎓</div><div><div style="font-size:28px;font-weight:700;">{{ saas.totalStudents || 0 }}</div><div style="color:#64748B;font-size:14px;">Students</div></div></div>
      </div>
      <div class="grid-2" style="margin-top:20px;">
        <div class="card">
          <h3 style="margin-bottom:16px;">Revenue by Subscription</h3>
          <table>
            <thead><tr><th>Plan</th><th>Tenants</th></tr></thead>
            <tbody>
              <tr *ngFor="let line of saas.orgsBySubscription"><td>{{ line.name }}</td><td>{{ line.usageCount }}</td></tr>
              <tr *ngIf="!saas.orgsBySubscription || saas.orgsBySubscription.length === 0">
                <td colspan="2" style="text-align:center;color:#64748B;padding:24px;">No subscriptions assigned yet</td>
              </tr>
            </tbody>
          </table>
        </div>
        <div class="card">
          <h3 style="margin-bottom:16px;">Recent Organizations</h3>
          <table>
            <thead><tr><th>Org</th><th>Plan</th><th>Status</th></tr></thead>
            <tbody>
              <tr *ngFor="let org of saas.recentOrganizations">
                <td>{{ org.name }}</td><td>{{ org.orgSubscriptionName || '-' }}</td>
                <td><span [style.color]="org.isActive ? '#22C55E' : '#F87171'">{{ org.isActive ? 'Active' : 'Inactive' }}</span></td>
              </tr>
              <tr *ngIf="!saas.recentOrganizations || saas.recentOrganizations.length === 0">
                <td colspan="3" style="text-align:center;color:#64748B;padding:24px;">No organizations yet</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    } @else {
      <h1 style="font-size:24px;font-weight:700;margin-bottom:24px;">Dashboard</h1>
      <div class="grid-4">
        <div class="card stat-card"><div class="icon" style="background:#DBEAFE;color:#2563EB;">👥</div><div><div style="font-size:28px;font-weight:700;">{{stats.totalStudents || 0}}</div><div style="color:#64748B;font-size:14px;">Total Students</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#FEF3C7;color:#EAB308;">📚</div><div><div style="font-size:28px;font-weight:700;">{{stats.activeCourses || 0}}</div><div style="color:#64748B;font-size:14px;">Active Courses</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#F3E8FF;color:#9333EA;">🎯</div><div><div style="font-size:28px;font-weight:700;">{{stats.placementPercentage || 0}}%</div><div style="color:#64748B;font-size:14px;">Placement Rate</div></div></div>
        <div class="card stat-card"><div class="icon" style="background:#DCFCE7;color:#22C55E;">💰</div><div><div style="font-size:28px;font-weight:700;">₹{{stats.totalRevenue | number:'1.0-0'}}</div><div style="color:#64748B;font-size:14px;">Revenue</div></div></div>
      </div>
    }
  `,
  styles: [`
    .stat-card { display:flex; align-items:center; gap:16px; }
    .icon { width:48px; height:48px; border-radius:12px; display:flex; align-items:center; justify-content:center; font-size:24px; }
  `]
})
export class DashboardComponent implements OnInit {
  auth = inject(AuthService);
  saas: SaasStats = {
    totalOrganizations: 0, activeOrganizations: 0, totalOrgAdmins: 0, totalTeachers: 0,
    totalStudents: 0, totalUsers: 0, totalSubscriptions: 0, mrr: 0,
    orgsBySubscription: [], recentOrganizations: []
