    } else {
      this.loadDashboardStats();
    }
  }

  loadSaasStats() {
    this.apiService.get<SaasStats>('/api/saas/stats').subscribe({
      next: (data) => (this.saas = data),
      error: (err) => console.error('Failed to load SaaS stats', err)
